mapper.insert:
INSERT INTO HOUSE (
    PRTNR_SN, HOUSE_NM, ZIP, ADDR, DADDR, HOUSE_DC, SIDO_REGION_CD, SIGUNGU_REGION_CD,
    REG_DT, MDFCN_DT, RGTR_SN
) VALUES (
    #{prtnrSn}, #{houseNm}, #{zip}, #{addr}, #{daddr}, #{houseDc}, #{sidoRegionCd}, #{sigunguRegionCd},
    UTC_TIMESTAMP(6), UTC_TIMESTAMP(6), #{rgtrSn}
)

mapper.sql:
WHERE H.PRTNR_SN = #{prtnrSn}
  AND H.DEL_YN = 'N'
 AND H.HOUSE_STTS_CD = #{status} 

    AND H.HOUSE_NM LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'

mapper.update:
UPDATE HOUSE
   SET HOUSE_STTS_CD = #{houseSttsCd},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE HOUSE_SN = #{houseSn}
   AND PRTNR_SN = #{prtnrSn}
   AND DEL_YN = 'N'
   AND HOUSE_STTS_CD <> 'SUSPENDED'

UPDATE HOUSE
   SET WEEKDAY_RATE_AMT  = #{weekdayRateAmt},
       FRIDAY_RATE_AMT   = #{fridayRateAmt},
       SATURDAY_RATE_AMT = #{saturdayRateAmt},
       PEAK_RATE_AMT     = #{peakRateAmt},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE HOUSE_SN = #{houseSn}
   AND PRTNR_SN = #{prtnrSn}
   AND DEL_YN = 'N'

UPDATE HOUSE
   SET CLOSED_WKDAY_CD         = #{closedWkdayCd},
       HOLIDAY_CLOSED_YN       = #{holidayClosedYn},
       LUNAR_HOLIDAY_CLOSED_YN = #{lunarHolidayClosedYn},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE HOUSE_SN = #{houseSn}
   AND PRTNR_SN = #{prtnrSn}
   AND DEL_YN = 'N'

UPDATE HOUSE
   SET DEL_YN = 'Y',
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE HOUSE_SN = #{houseSn}
   AND PRTNR_SN = #{prtnrSn}
   AND DEL_YN = 'N'

mapper.sql:
WHERE H.DEL_YN = 'N'
 AND H.HOUSE_STTS_CD = #{status} 
 AND H.PRTNR_SN = #{prtnrSn} 
 AND H.SIDO_REGION_CD = #{sidoRegionCd} 
 AND H.SIGUNGU_REGION_CD = #{sigunguRegionCd} 


    AND ( H.HOUSE_NM LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\'
          OR EXISTS (SELECT 1 FROM PRTNR_MST PK
                      WHERE PK.PRTNR_SN = H.PRTNR_SN
                        AND PK.CONM LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\') )

mapper.update:
UPDATE HOUSE
   SET HOUSE_STTS_CD = #{toSttsCd},
       MDFCN_DT = UTC_TIMESTAMP(6),
       MDFR_SN = #{mdfrSn}
 WHERE HOUSE_SN = #{houseSn}
   AND DEL_YN = 'N'
   AND HOUSE_STTS_CD = #{fromSttsCd}

